// JIDs verificados em 11/09/2026 via GET /group/fetchAllGroups (id único por nome)
const JID_GRUPO_RENATO = '120363425586360506@g.us';      // RDO - Equipe Emergencial Renato
const JID_GRUPO_WELLINGTON = '120363407044425576@g.us';  // RDO - Equipe Emergencial Wellington
const JID_GRUPO_PADRAO = '120363405209036533@g.us';      // RDO - Manutenção Preventiva/Emergencial
const APP_CAMPO = 'https://fpvieira.vercel.app';
function grupoDoFiscal(f){ f = String(f||'').toLowerCase(); if(f.includes('renato')) return JID_GRUPO_RENATO; if(f.includes('welling')) return JID_GRUPO_WELLINGTON; return JID_GRUPO_PADRAO; }
// deep link: o colaborador clica no grupo e cai no app de campo com a O.S.
// já preenchida (v109 do FPV-Campo lê ?os=&un=&ar=&ni=&as=&de=&fi=&dt=)
function linkApp(o){
  const par = [];
  const poe = (k, v) => { v = String(v == null ? '' : v).trim(); if(v) par.push(k + '=' + encodeURIComponent(v)); };
  poe('os', o.numero);
  poe('un', o.unidade);
  poe('ar', o.area);
  poe('ni', o.nivel);
  poe('as', o.assunto);
  poe('de', Array.from(String(o.descricao||'')).slice(0, 350).join('')); // corte por code point: emoji na fronteira NAO derruba o encodeURIComponent (e a fila)
  poe('fi', o.fiscal);
  poe('dt', String(o.data_abertura||'').slice(0, 10));
  return APP_CAMPO + '/?' + par.join('&');
}
const brutos = $input.all().map(i => i.json);
const lista = (brutos.length === 1 && Array.isArray(brutos[0])) ? brutos[0] : brutos;
return lista.filter(o => o && o.numero).map(o => {
  const resumo = 'O.S. ' + o.numero + ' — ' + o.unidade + '\nÁrea: ' + o.area + ' · Nível ' + o.nivel + '\nAssunto: ' + o.assunto + '\nServiço: ' + o.descricao + '\nAbertura: ' + String(o.data_abertura||'').split('-').reverse().join('/') + ' · Fiscal: ' + (o.fiscal||'') + '\nEmitida por: ' + (o.emitida_por||'');
  return { json: {
    ...o,
    grupoJid: grupoDoFiscal(o.fiscal),
    link: 'https://irprgdzaqoqnjuksuloh.supabase.co/storage/v1/object/public/os-oficiais/os-' + o.numero + '.xlsx',
    nomeArquivo: 'OS ' + o.numero + ' - ' + String(o.assunto||'').toUpperCase().replace(/[\\/:*?"<>|]/g,'-') + ' - ' + o.area + ' - ' + String(o.unidade||'').replace(/[\\/:*?"<>|]/g,'-') + '.xlsx',
    resumo: resumo,
    caption: resumo + '\n\n\ud83d\udcf2 Registrar a execução no app: ' + linkApp(o)
  } };
});
